<script>
(() => {
    const modal = document.querySelector('[data-invoice-modal]');
    const openButton = document.querySelector('[data-invoice-open]');
    const close = () => { if (!modal) return; modal.hidden = true; document.body.classList.remove('service-invoice-open'); };
    openButton?.addEventListener('click', () => { if (!modal) return; modal.hidden = false; document.body.classList.add('service-invoice-open'); modal.querySelector('.service-invoice-close')?.focus(); });
    modal?.querySelectorAll('[data-invoice-close]').forEach((button) => button.addEventListener('click', close));
    const reminderModal = document.querySelector('[data-reminder-modal]');
    const reminderOpenButton = document.querySelector('[data-reminder-open]');
    const reminderClose = () => { if (!reminderModal) return; reminderModal.hidden = true; document.body.classList.remove('service-reminder-open'); };
    reminderOpenButton?.addEventListener('click', () => { if (!reminderModal) return; reminderModal.hidden = false; document.body.classList.add('service-reminder-open'); reminderModal.querySelector('.service-reminder-close')?.focus(); });
    reminderModal?.querySelectorAll('[data-reminder-close]').forEach((button) => button.addEventListener('click', reminderClose));
    document.addEventListener('keydown', (event) => { if (event.key !== 'Escape') return; close(); reminderClose(); });
})();
</script>
