    const openDecision = (approval, decision) => { pendingDecision = { approval, decision }; decisionDialog.querySelector('[data-decision-title]').textContent = decision === 'approve' ? 'Setujui pekerjaan tambahan?' : 'Tolak pekerjaan tambahan?'; decisionDialog.querySelector('[data-decision-copy]').textContent = decision === 'approve' ? 'Anda menyetujui YZA melakukan pekerjaan tambahan ini sesuai estimasi yang ditampilkan.' : 'YZA tidak akan mengerjakan pekerjaan tambahan yang Anda tolak.'; decisionDialog.querySelector('[data-decision-note]').value = ''; decisionDialog.showModal(); };
    document.querySelectorAll('[data-member-approval-decision]').forEach(button => button.addEventListener('click', () => openDecision({ id: Number(button.dataset.approvalId), title: button.closest('.member-approval-card')?.querySelector('h4')?.textContent || 'Pekerjaan tambahan', estimated_additional_total: 0 }, button.dataset.memberApprovalDecision)));
    const renderApprovals = data => { const rows = data.approvals || []; approvals.innerHTML = '<span class="member-approval-eyebrow">⚠ TINDAKAN ANDA DIPERLUKAN</span><h3>PERSETUJUAN PEKERJAAN TAMBAHAN</h3>'; if (!rows.length) { approvals.insertAdjacentHTML('beforeend', '<p>Tidak ada pekerjaan tambahan yang menunggu persetujuan Anda.</p>'); return; } approvals.insertAdjacentHTML('beforeend', '<p>YZA menemukan pekerjaan tambahan yang membutuhkan persetujuan Anda sebelum dikerjakan.</p>'); rows.forEach(approval => { const card = document.createElement('article'); card.className = 'member-approval-card'; const items = (approval.items || []).map(item => `<div class="member-approval-item"><div class="member-approval-item-copy"><strong>${item.description || 'Item tambahan'}</strong><small>${item.type === 'labor' ? 'Jasa' : 'Sparepart'} · Qty ${item.quantity || 0}</small></div><div class="member-approval-item-prices"><span>Harga Satuan <b>${money(item.unit_price)}</b></span><span>Subtotal <b>${money(item.total)}</b></span></div></div>`).join(''); card.innerHTML = `<h4>${approval.title || 'Pekerjaan tambahan'}</h4><p>${approval.reason || ''}</p><small>Diminta: ${approval.requested_at || '—'}</small><div class="member-approval-items">${items}</div><div class="member-approval-total"><span>Estimasi Tambahan</span><strong>${money(approval.estimated_additional_total)}</strong></div><span class="member-approval-status ${approval.status === 'pending' ? 'is-pending' : approval.status === 'approved' ? 'is-approved' : 'is-rejected'}">${approval.status === 'pending' ? 'Menunggu Keputusan' : approval.status === 'approved' ? '✓ DISETUJUI' : 'DITOLAK'}</span>`; if (approval.status === 'pending') { const actions = document.createElement('div'); actions.className = 'member-approval-actions'; const approve = document.createElement('button'); approve.type = 'button'; approve.textContent = 'SETUJUI PEKERJAAN'; approve.addEventListener('click', () => openDecision(approval, 'approve')); const reject = document.createElement('button'); reject.type = 'button'; reject.textContent = 'TOLAK'; reject.addEventListener('click', () => openDecision(approval, 'reject')); actions.append(reject, approve); card.appendChild(actions); } approvals.appendChild(card); }); if (window.location.hash === '#approval') approvals.scrollIntoView({ block: 'start' }); };
    const loadAll = async () => { refreshButton.disabled = true; errorBox.hidden = true; current.innerHTML = '<strong>Memuat status servis…</strong><span>Mohon tunggu sebentar.</span>'; timeline.innerHTML = '<div class="member-execution-loading">Memuat timeline servis…</div>'; try { const [trackingResponse, approvalsResponse] = await Promise.all([fetch(trackingUrl, { headers: { Accept: 'application/json' } }), fetch(approvalsUrl, { headers: { Accept: 'application/json' } })]); if (!trackingResponse.ok || !approvalsResponse.ok) throw new Error('backend_unavailable'); const tracking=await trackingResponse.json(); renderTracking(tracking); if (tracking.current_stage === 'completed') { const actions=document.createElement('div'); actions.className='member-execution-actions'; actions.innerHTML=`${invoiceUrl ? `<a href="${invoiceUrl}">Lihat Invoice</a>` : ''}<a href="${historyUrl}">Lihat Riwayat Servis</a><a href="{{ route('pelanggan.kendaraan.index') }}">Kembali ke Kendaraan Saya</a>`; current.appendChild(actions); } renderApprovals(await approvalsResponse.json()); } catch (error) { console.error('Member approval data gagal dimuat', error); current.innerHTML = '<strong>Status execution belum tersedia.</strong><span>Data akan tampil setelah layanan execution YZA aktif.</span>'; timeline.innerHTML = '<div class="member-execution-loading">Timeline belum dapat dimuat.</div>'; approvals.innerHTML = '<h3>PERSETUJUAN PEKERJAAN TAMBAHAN</h3><p>Persetujuan pekerjaan tambahan belum dapat dimuat.</p><button type="button" data-execution-retry>Coba Lagi</button>'; approvals.querySelector('[data-execution-retry]')?.addEventListener('click', loadAll); showError('Persetujuan pekerjaan tambahan belum dapat dimuat.'); } finally { refreshButton.disabled = false; } };
    decisionDialog.querySelector('[data-decision-cancel]').addEventListener('click', () => decisionDialog.close()); decisionDialog.querySelector('[data-decision-submit]').addEventListener('click', async event => { event.preventDefault(); if (!pendingDecision) return; const submit = event.currentTarget; submit.disabled = true; submit.textContent = 'Memproses…'; const note = decisionDialog.querySelector('[data-decision-note]').value; try { const response = await fetch(`${approvalsUrl}/${pendingDecision.approval.id}/decision`, { method: 'POST', headers: { Accept: 'application/json', 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '' }, body: JSON.stringify({ decision: pendingDecision.decision, note }) }); if (!response.ok) throw new Error('decision'); decisionDialog.close(); await loadAll(); } catch (_) { decisionDialog.close(); showError('Keputusan belum dapat disimpan. Silakan coba lagi.'); } finally { submit.disabled = false; submit.textContent = 'Konfirmasi'; pendingDecision = null; } }); refreshButton.addEventListener('click', loadAll); loadAll();
})();
</script>
@endpush
